import { timePickerReducer } from "./TimePicker";

describe("TimePicker reducer", () => {
  it("update input with separators", () => {
    const initialState = {
      input: "",
      invalid: false,
      period: "am",
      use12Hours: false,
    };

    let updatedState = timePickerReducer(initialState, {
      type: "updateInput",
      input: "12",
      addSeparators: true,
      selectionStart: null,
    });
    expect(updatedState.input).toEqual("12:");

    updatedState = timePickerReducer(initialState, {
      type: "updateInput",
      input: "1212",
      addSeparators: true,
      selectionStart: null,
    });
    expect(updatedState.input).toEqual("12:12");
    expect(updatedState.match).toEqual("12:12");
  });

  it("check invalid input", () => {
    const initialState = {
      input: "",
      invalid: false,
      period: "am",
      use12Hours: false,
    };

    expect(
      timePickerReducer(
        { ...initialState, input: "55" },
        { type: "checkInput" }
      ).invalid
    ).toBeTruthy();
    expect(
      timePickerReducer(
        { ...initialState, input: "55:55" },
        { type: "checkInput" }
      ).invalid
    ).toBeTruthy();
    expect(
      timePickerReducer(
        { ...initialState, input: "12:12" },
        { type: "checkInput" }
      ).invalid
    ).toBeFalsy();
  });

  it("update period", () => {
    const initialState = {
      input: "12:12",
      invalid: false,
      period: "am",
      use12Hours: true,
    };

    let updatedState = timePickerReducer(initialState, {
      type: "updatePeriod",
      period: "pm",
    });
    expect(updatedState.match).toEqual("12:12 pm");
  });
});
